mapper.select:
SELECT count(*)
  FROM crm12_work_detail
 WHERE crm12_work_detail_id = #{workDetailId}
   AND crm12_company_id     = #{companyId}

mapper.update:
UPDATE crm12_work_detail
   SET crm12_work_date    = #{req.workDate}
     , crm12_work_nm      = #{req.workName}
     , crm12_work_content = #{req.workContent}
     , crm12_private_yn   = #{req.privateYn}::text
 WHERE crm12_work_detail_id = #{req.workDetailId}
   AND crm12_company_id     = #{companyId}

mapper.delete:
DELETE FROM crm13_relate_fund
 WHERE crm13_relate_fund_id = #{relateFundId}
   AND crm13_work_detail_id IN ( SELECT crm12_work_detail_id FROM crm12_work_detail WHERE crm12_company_id = #{companyId} )
